interface BreadcrumbItem {
  id?: string;
  label: React.ReactNode;
  href?: string;
  disabled?: boolean;
}

interface BreadcrumbsOwnProps {
  items?: BreadcrumbItem[];
  onNavigate?: (item: BreadcrumbItem) => void;
}

interface BreadcrumbsProps extends BreadcrumbsOwnProps, Omit<React.HTMLAttributes<HTMLElement>, keyof BreadcrumbsOwnProps | 'children' | 'className' | 'aria-label'> {
  className?: string;
  'aria-label': string;
}
